CH = dict(num=7, tag="Polity", theme="Evolution, principles, types and challenges of democracy in India",
 title="Democracy",
 intro="Democracy is the form of government in which power rests with the citizens, who choose their representatives in free and fair elections. This chapter traces the roots of democratic ideas in India, the constitutional principles that sustain them, the forms of democracy in the world, how India's democracy lives at the grassroots, and the challenges it faces.",
 big_questions=["How has the idea of democracy evolved and shaped our understanding today?", "What forms of democracy exist and how are they practised in India and elsewhere?", "What are the essential features of democracy beyond government institutions?", "What challenges does Indian democracy face?"],
 blocks=[
 ("h2", "India: The World's Largest Democracy"),
 ("ul", ["India has a population of over **140 crore** and over **96.8 crore** registered voters (2024): the largest participatory democracy.", "The **Constitution of India** was **adopted on 26 November 1949** and **came into force on 26 January 1950**. It guarantees and protects Fundamental Rights and bars discrimination on grounds of religion, race, caste, sex or place of birth; it encourages participation at national, state and local levels.", "Democratic ethos did not arise suddenly; it grew over a long historical process."]),
 ("h2", "Tracing Democratic Traditions from Early Times"),
 ("ul", ["**Vedic assemblies** (sabhā, samiti, vidhata) and early **republics (gaṇas/saṁghas)** show collective decision-making; the king worked in consultation with assemblies, ministers and officers.", "The **Aikyamatya Sūktam** (Ṛigveda 10.191.3) stresses one counsel, one assembly, one mind: consultation, consensus and shared responsibility.", "The **Bauddha Saṁghas** (Buddha's monastic community) encouraged debate, chose their leader and decided by voting.", "Foreign invasions and, by the 19th century, **British colonisation** limited participation, but the **freedom struggle** revived democratic ideas.", "The **Constituent Assembly** was formed in **1946** and took **2 years, 11 months and 18 days** to draft the world's longest written constitution. **Dr B.R. Ambedkar** chaired the Drafting Committee. Its debates (CAD) wanted a flexible, dynamic constitution; **Article 368** allows amendments without compromising basic values (liberty, equality, justice, fraternity)."]),
 ("h2", "Principles of Democracy"),
 ("table", ["Principle", "Meaning and constitutional provisions"], [
  ["**Popular sovereignty**", "Ultimate power lies with the people; the state derives authority from them. Citizens aged **18 and above** vote by **secret ballot**: **Universal Adult Franchise**. (*Sovereignty* from Latin *superanus* 'supreme': the supreme, independent legal authority of a state over its territory and citizens.)"],
  ["**Rule of law**", "Equality before law and equal protection; nobody is above the law; disputes settled in courts; no punishment except by **procedure established by law** (**Article 21**: no one deprived of life or personal liberty except by this procedure). *Equality before law* = same treatment irrespective of rank; *equal protection* = like persons in like circumstances treated alike, without arbitrary discrimination"],
  ["**Fundamental Rights**", "Protect freedom and dignity; enforceable in courts; reasonable restrictions possible"],
  ["**Separation of powers**", "Legislature makes laws, executive implements, judiciary interprets, preventing concentration of power and creating checks and balances; the judiciary can declare a law unconstitutional and review amendments. **PIL** (Public Interest Litigation) widens access to justice"],
  ["**Accountability and transparency**", "Government answerable to citizens through elections, debate, civil society; **RTI Act, 2005**; Question Hour; audit of accounts"],
  ["**Multi-party system**", "Many parties represent diverse interests; the party/coalition with more than 50% seats forms the government, the largest opposing group becomes the opposition; governed by the **Representation of the People Act, 1951**"],
  ["**Protection of vulnerable groups**", "Equitable resource distribution. **Article 46**: State shall promote with special care the educational and economic interests of weaker sections, especially SCs and STs, and protect them from social injustice and exploitation"]]),
 ("table", ["Fundamental Right", "Articles"], [["Right to Equality", "14–18"], ["Right to Freedom", "19–22"], ["Right against Exploitation", "23–24"], ["Right to Freedom of Religion", "25–28"], ["Cultural and Educational Rights", "29–30"], ["Right to Constitutional Remedies", "32 (and 226 for High Courts)"]]),
 ("note", "NOTE", "**Right to Education (Article 21A)**, added in 2009, gives free and compulsory education to children aged 6 to 14. The Constitution also contains Fundamental Duties and Directive Principles of State Policy."),
 ("h3", "Institutions and the values they promote"),
 ("table", ["Process", "Institution", "Values"], [["Legislative", "Parliament, State legislatures, local bodies", "Representation, deliberation, dissent"], ["Electoral", "Election Commission of India", "Participation, equality"], ["Judicial", "Courts", "Rule of law, equality, justice"], ["Participatory", "Media, civil society", "Debate, discussion, freedom of expression"], ["Accountability and transparency", "CAG, Central Information Commission, Lokpal, Central Vigilance Commission", "Transparency"], ["Decentralisation", "Rural and urban local bodies", "People's participation at grassroots"], ["Federalism", "Division of powers between Centre and states by a written constitution", "Devolution of power"]]),
 ("note", "DEFINITION", "**Civil society:** voluntary groups, NGOs and community associations functioning within society. The **media** is called the **fourth pillar of democracy** because it informs people and voices public issues. In Question Hour, members question the government."),
 ("h2", "Types of Democracy"),
 ("table", ["", "Direct democracy", "Representative (indirect) democracy"], [["Who decides", "Citizens take part directly in most decisions", "People elect representatives; they do not govern directly"], ["Suitability", "Hard in large countries", "Suits large countries; periodic elections; government accountable"], ["Example", "Switzerland", "India"]]),
 ("table", ["", "Parliamentary", "Presidential"], [["Executive", "Part of the legislature and accountable to it", "Independent of the legislature"], ["Head", "People elect legislature, not executive", "President elected by people and accountable to them"], ["Examples", "India, Canada", "USA"]]),
 ("p", "Democracy has no single model: freedom, equality, participation, rule of law, rights and duties are common, but forms differ. (The school-council example: Team A direct; Team B representative; Team C presidential; Team D has elections but concentrated power and weak opposition, so it is not truly democratic.)"),
 ("table", ["Country", "Type", "Executive / head", "Key features"], [
  ["India", "Parliamentary representative", "PM (head of government), President (head of state)", "Multi-party; written constitution; federal (Union, State, Concurrent lists; residual powers with Union)"],
  ["Canada", "Parliamentary", "PM; Governor-General appointed by the Monarch on PM's advice", "Federalism, multi-party"],
  ["United Kingdom", "Parliamentary constitutional monarchy", "Monarch (head of state), PM", "Unwritten constitution, parliamentary sovereignty"],
  ["Switzerland", "Direct democracy", "Federal Council; President is head of government", "Written constitution, many parties"],
  ["USA", "Presidential", "President is head of government", "Written constitution, two major parties"]]),
 ("note", "DEFINITION", "**Federalism:** a system in which power and responsibilities are shared between the Union and the state governments."),
 ("h2", "Democracy in Practice: India's Living Democracy"),
 ("ul", ["An MP represents on average about **25 lakh** people (2019). Elections are held in **22 scheduled languages** and more; **election symbols** let non-readers vote. More than **one million polling stations**, even in mountains, forests, deserts and islands (sometimes for one voter). Over **2,800** registered political parties.", "**Participatory democracy** stresses citizens' involvement beyond voting. India has a three-tier system: Union, State, Local. Autonomous District Councils (ADCs) in certain north-eastern areas have legislative and judicial powers to preserve tribal customs; the **PESA Act, 1996** empowers the **Gram Sabha** in tribal areas of other states."]),
 ("h3", "Case study: democracy at the grassroots"),
 ("table", ["Panchayat", "Achievements"], [["**Jethipura Gram Panchayat** (Idar block, Sabarkantha, Gujarat)", "Won the **Nanaji Deshmukh Rashtriya Gaurav Gram Sabha Puraskar** (2019): effective Gram Sabhas, record keeping, special Gram Sabhas, Mahila Sabhas, adequate **quorum** and participation of SCs, STs and women; action on education, sanitation, welfare"], ["**South Manubankul Gram Panchayat** (Rupaichari, Tripura)", "Nationally recognised as a **women-friendly panchayat** by the Ministry of Panchayati Raj: women in decision-making, health, sanitation, livelihoods, self-help groups"]]),
 ("p", "Democratic habits also appear in cooperatives (members share profits and responsibilities), trade unions, civil society and community institutions."),
 ("h2", "Women and the Right to Vote"),
 ("ul", ["Women got full voting rights in **Britain in 1928** and the **USA in 1920** after long struggles; in India the 1950 Constitution gave **universal adult franchise** to men and women alike, without a struggle. Yet social prejudice still limits women's representation.", "**Article 243(d)**: not less than one-third of seats in every Panchayat reserved for women; **21 States and 2 UTs** provide 50%. **Article 243(t)**: one-third in every Municipality; as of 2023, **17 States and 1 UT** provide 50% in urban local bodies."]),
 ("note", "NOTE", "**RTI Act, 2005** came through Parliament after citizens, journalists and civil society raised transparency concerns, parliamentary committees and expert groups examined them, and elected representatives added safeguards for national security and administrative efficiency. It lets citizens seek information from public authorities."),
 ("h2", "Challenges to Democratic Practices in India"),
 ("ul", ["Rights come with responsibilities. Damaging public property, spreading misinformation or ignoring public issues weakens democracy.", "Challenges: **illiteracy, misinformation and fake news** (especially on social media), **inequality, poverty, regionalism, gender inequality, social discrimination** and gaps in implementing laws, which reduce trust in institutions."]),
 ("h3", "The Emergency (1975–77)"),
 ("ul", ["Early 1970s: unemployment, inflation and allegations of misgovernance under **Indira Gandhi** led to protests. In **June 1975** a National Emergency was declared on grounds of internal disturbance (**Articles 352, 356, 360**: National Emergency, President's Rule, Financial Emergency).", "Most Fundamental Rights were suspended, press censored, leaders and activists arrested. Mass movements led by **Jayaprakash Narayan (Lok Nayak)** mobilised people, especially in Bihar and Gujarat.", "Lifted in **1977**; the ruling government lost the general election, showing the strength of democracy and the need for constitutional safeguards, civil liberties and citizen vigilance."]),
 ("h3", "Democracy and you"),
 ("p", "Be well-informed and media literate; follow Fundamental Duties; understand the Constitution; join **NSS, NCC, Bharat Scouts and Guides**; show leadership at school and in the community. **Civic responsibility** includes respecting others' rights, using social media responsibly, obeying laws, valuing diversity and supporting unity."),
 ("h2", "Quick Revision: Likely Exam Questions"),
 ("qa", [
  ("What is democracy?", "Government in which power rests with the people, who elect representatives in free and fair elections."),
  ("Show that democratic ideas are rooted in ancient India.", "Sabhā, samiti, vidhata, gaṇas/saṁghas, Aikyamatya Sūktam and the Bauddha Saṁgha's voting."),
  ("How long did the Constituent Assembly take to draft the Constitution?", "2 years, 11 months and 18 days; formed in 1946."),
  ("What is popular sovereignty and Universal Adult Franchise?", "Power derives from the people; every citizen of 18+ may vote by secret ballot."),
  ("Explain the rule of law.", "Equal law for all, disputes in courts, no punishment without procedure established by law (Article 21)."),
  ("List the six Fundamental Rights with articles.", "Equality 14–18; Freedom 19–22; Against Exploitation 23–24; Religion 25–28; Cultural and Educational 29–30; Constitutional Remedies 32."),
  ("Explain separation of powers.", "Legislature makes, executive implements, judiciary interprets laws, giving checks and balances."),
  ("How is accountability ensured?", "Elections, debates, Question Hour, audit (CAG), RTI Act 2005, CIC, Lokpal, CVC."),
  ("Distinguish direct and representative democracy.", "Direct: citizens decide (Switzerland). Representative: elected representatives decide (India)."),
  ("Differentiate parliamentary and presidential democracy.", "Parliamentary: executive accountable to the legislature (India, Canada). Presidential: separately elected President (USA)."),
  ("Why is India called the largest democracy?", "Over 96.8 crore voters, huge polling network, many languages, 2,800+ parties."),
  ("What reservation exists for women in local bodies?", "Not less than one-third (Art. 243(d), 243(t)); many states give 50%."),
  ("What were the causes and effects of the Emergency?", "Economic distress and protests led to its imposition in 1975; rights and press curbed; lifted in 1977 and the government lost the election."),
  ("Name challenges to Indian democracy.", "Illiteracy, fake news, inequality, poverty, regionalism, gender and social discrimination, weak implementation."),
  ("Why is media called the fourth pillar?", "It informs citizens and voices public issues, holding government accountable."),
 ]),
 ],
 takeaways=["Democracy means self-governance by participation, not just elections.", "India's democratic roots lie in Vedic assemblies, republics and Buddhist Saṁghas; the Constitution (1950) gives it modern form.", "Key principles: popular sovereignty, rule of law, Fundamental Rights, separation of powers, accountability, multi-party system, protection of the vulnerable.", "Democracy has many forms: direct or representative, parliamentary or presidential.", "Local bodies, women's reservation and RTI deepen grassroots democracy.", "Fake news, inequality and illiteracy are challenges; the Emergency showed both vulnerability and resilience; informed, responsible citizens sustain democracy."])
